import{z as n,x as s,o as e,c as p,q as B,j as t,D as E,d as i,s as l,S as o}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"曲线 MRC","description":"","frontmatter":{"title":"曲线 MRC","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/curvilinear-mrc.md","filePath":"litho/curvilinear-mrc.md","lastUpdated":1791413859000}'),C={name:"litho/curvilinear-mrc.md"};function A(d,a,h,c,m,_){const r=s("Mermaid");return e(),p("div",null,[a[2]||(a[2]=B('<h1 id="曲线-mrc" tabindex="-1">曲线 MRC <a class="header-anchor" href="#曲线-mrc" aria-label="Permalink to &quot;曲线 MRC&quot;">​</a></h1><div class="epigraph"><p>曼哈顿规则量的是平行边距离；曲线掩模的颈、曲率半径和孔圆度是另一套可写性语言，必须按多束栅格重写。</p><footer>—— 对照多束写入与曲线 ILT 的公开可制造性讨论</footer></div><p><a href="/litho/mrc-fixup">上一课</a>（MRC 修复）。把可写集合写成多边形 MRC：宽、距、面积、jog。缺口是 ILT 的自然输出不是直角。曲边上「最小间距」不再是两条平行边的距离，颈宽、曲率、面积与检测算法全部要换定义。多束机把写入从炮数换成面积，但栅格分辨率和 PEC 仍拒绝过尖的拐、过细的颈。本课钉曲线 MRC。多束与 VSB 的写入物理对照，留给后课与<a href="/litho/multibeam-mask-writer">多束写入</a>衔接。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把曲线先折成大量微矩形，再跑旧 MRC，会得到两种假结果：要么微矩形自己违例（ jog 爆炸），要么折线「通过」而真实曲颈在蚀刻后断开。曲线 MRC 的对象是样条或曲边多边形：最小曲率半径、最小颈宽、孔/岛的最小面积与圆度、相邻曲线的最小间隙（沿法向而非沿轴）。</p><p>为什么「折成微矩形 + 旧规则」两头都错？因为同一条光滑曲边，在曼哈顿检查器和真实写入器眼里是两个不同的对象：前者看到的是成千上万个锯齿台阶，后者看到的是一段连续的曲颈。两边各自报出一个相反的错误结论。</p>',6)),(e(),t(o,null,{default:E(()=>[l(r,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%85%89%E6%BB%91%E6%9B%B2%E8%BE%B9%22%5D%20--%3E%20F%5B%22%E6%8A%98%E6%88%90%E5%BE%AE%E7%9F%A9%E5%BD%A2%22%5D%0A%20%20F%20--%3E%20OLD%5B%22%E8%B7%91%E6%9B%BC%E5%93%88%E9%A1%BF%20MRC%22%5D%0A%20%20OLD%20--%3E%20R1%7B%22%E7%BB%93%E6%9E%9C%EF%BC%9F%22%7D%0A%20%20R1%20--%3E%7C%22%E9%94%AF%E9%BD%BF%E9%97%B4%20jog%20%E8%BF%9D%E4%BE%8B%22%7C%20FA%5B%22%E5%81%87%E8%BF%9D%E4%BE%8B%EF%BC%9A%E5%90%88%E6%B3%95%E6%9B%B2%E8%BE%B9%E8%A2%AB%E6%8B%92%22%5D%0A%20%20R1%20--%3E%7C%22%E5%8F%B0%E9%98%B6%E5%90%88%E5%B9%B6%E5%90%8E%E9%80%9A%E8%BF%87%22%7C%20FB%5B%22%E5%81%87%E9%80%9A%E8%BF%87%EF%BC%9A%E7%9C%9F%E6%9B%B2%E9%A2%88%E8%BF%87%E7%BB%86%22%5D%0A%20%20FB%20--%3E%20ET%5B%22%E8%9A%80%E5%88%BB%E5%90%8E%E9%A2%88%E5%8C%BA%E6%96%AD%E5%BC%80%22%5D%0A%20%20FA%20--%3E%20FIX%5B%22%E6%94%B9%E7%94%A8%E6%9B%B2%E7%BA%BF%20MRC%EF%BC%9A%E6%9B%B2%E7%8E%87%20%2F%20%E9%A2%88%E5%AE%BD%20%2F%20%E6%B3%95%E5%90%91%E9%97%B4%E9%9A%99%22%5D%0A%20%20ET%20--%3E%20FIX%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B('<p>检测（掩模 SEM、光化检验）若仍用直角边算法，会把合法曲边当缺陷，或漏掉真缺陷。ILT 项目失败常常失败在这条后处理与检测链，而不是优化没收敛。缺口是规则、数据格式、计量一起换，而不是只允许多束。</p><p><span class="marginnote">术语翻译：MRC（掩模规则检查）就是掩模版世界的设计规则检查——图形交给写板机之前，先用一套几何下限（最小线宽、最小间距、最小曲率半径、最小颈宽）确认「这版图形写得出来、蚀得出来」。曲线掩模不是豁免检查，而是换一本用曲线语言写的规则书。</span></p><p><span class="marginnote">直觉类比：颈宽就是图形的「蜂腰」——一段收得再细的曲边在光学上都光滑，但像沙漏最细处，电子束写入和蚀刻都先从蜂腰断开。曲率半径则是「最小转弯半径」：弯打得太急（曲率太大），栅格化的「车轮」跟不上，形状就在位图上散架。</span></p><p><span class="marginnote">数字实例：设多束栅格 \\(5\\) nm、规则要求最小曲率半径 \\(20\\) nm，即圆弧至少要横跨 \\(4\\) 个束距才画得实；半径更小的弧在位图上只剩两三个像素，剂量补偿把它当噪声，印到硅上就偏。规则与栅格必须一起声明，缺一张，「光滑」就无从谈起。</span></p><h3 id="栅格是隐藏的一条规则" tabindex="-1">栅格是隐藏的一条规则 <a class="header-anchor" href="#栅格是隐藏的一条规则" aria-label="Permalink to &quot;栅格是隐藏的一条规则&quot;">​</a></h3><p>多束按位图或等效栅格曝光。曲率半径小于若干个束距，形状在栅格上退化成噪声，PEC 与剂量补偿失真。因此曲线 MRC 必须声明写入器栅格，而不能只给「光学上光滑」的连续曲线。公开叙事里，多束让写入时间对复杂度解耦；它没有让任意曲率免费。</p><p><span class="marginnote">「曲线」不是无规则。它是另一本规则书。把 MRC 关掉再展示窗口，不是曲线掩模的量产论证。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规则从掩模厂与多束供应商的公开能力出发：最小特征、剂量台阶、拼接缝连续性。计算侧在水平集或像素更新后，对提取的等值线做曲率裁剪、颈宽检查、间隙的法向距离检查，再投影回去。简化（降控制点）必须在 MRC 之后或之中做，否则简化本身制造新颈。</p><p>数据路径：曲线格式 → 分档 → PEC → 多束位图 → 二次曲线 MRC（对位图等效形状）。与曼哈顿流并行时，同一套版图的不同层可能一张走 VSB 规则、一张走曲线规则，签核工具要能分层套不同规则书。</p><h3 id="助条与曲颈" tabindex="-1">助条与曲颈 <a class="header-anchor" href="#助条与曲颈" aria-label="Permalink to &quot;助条与曲颈&quot;">​</a></h3><p>ILT 自发长出的助条往往是最细、曲率最大的部分，最先撞 MRC。鲁棒项若不允许它们印出，又要求它们够宽可写，可行集可能空。这时应放宽设计或改照明，而不是把曲颈规则降到写入器宣称的地板以下。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>光学低通并不关心直角还是圆角，只关心通带内的频谱。曲线 MRC 删掉的是通带外、却让写入和蚀刻失败的那些模态，所以合理的曲率裁剪对 PV-band 伤害应当很小——这是「曲线可写且仍有光学收益」的前提。若裁剪必须砍掉通带内的助条结构，收益消失，层就不该上全芯片曲线。</p><p>蚀刻微负载对曲边更平滑的密度场可能更友好，但颈区的局部负载仍尖锐。规则里的颈宽含蚀刻偏置，不能只用显影后模拟。阵列指纹（多束各通道电流不均）会在曲边上留下周期性粗糙，光学 OPC 修不掉，因为 OPC 假定掩模误差不是写入器周期指纹。</p><p><span class="marginnote">比较曲线与曼哈顿窗口时，双方都必须 MRC 干净。用未检查的像素解去对比已 MRC 的 OPC，是不对称实验。</span></p>',16)),(e(),t(o,null,{default:E(()=>[l(r,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20ILT%5B%22ILT%20%E7%AD%89%E5%80%BC%E7%BA%BF%22%5D%20--%3E%20CMRC%5B%22%E6%9B%B2%E7%BA%BF%20MRC%3A%20%E6%9B%B2%E7%8E%87%20%2F%20%E9%A2%88%20%2F%20%E9%97%B4%E9%9A%99%22%5D%0A%20%20CMRC%20--%3E%20GRID%5B%22%E5%AF%B9%E9%BD%90%E5%A4%9A%E6%9D%9F%E6%A0%85%E6%A0%BC%22%5D%0A%20%20GRID%20--%3E%20PEC%5B%22PEC%20%2B%20%E4%BD%8D%E5%9B%BE%22%5D%0A%20%20PEC%20--%3E%20MET%5B%22%E6%9B%B2%E8%BE%B9%E6%A3%80%E6%B5%8B%22%5D%0A%20%20CMRC%20--%3E%20BACK%5B%22%E6%8A%95%E5%BD%B1%E5%9B%9E%E6%B0%B4%E5%B9%B3%E9%9B%86%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>曲线 MRC 不消除空白片缺陷，不替代 pellicle，不提高 NA。它只定义多束 ILT 的可写流形。规则过严，曲线退回「圆了一点的曼哈顿」，GPU 白花；过松，掩模良率从「写不完」变成「测不准、修不好」。修补工具若只能贴曼哈顿补丁，会在曲谱上打出新热区。知识产权与数据比对也要换：曲线特征难以做传统「多边形等价」逐边核对，TAPOUT 合同必须另写比对口径。</p><p>后课默认：可写曲线已经受曲线 MRC 约束；下一跳是写入器家族——同一条曲线在 VSB 与多束上的时间墙完全不同。</p><p>多束课默认读者已经知道：曲线不是「关掉 MRC」，而是换了一本规则书。</p><p><span class="marginnote">引用多束 ILT 时写清 MRC 是否为曲线规则、检测是否为曲边算法。只报热区 clips 的窗口，不能外推到全芯片数据量与检测产能。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>曲线 MRC 用曲率、颈宽、法向间隙取代平行边距离。</li><li>必须对齐多束栅格；连续光滑不等于可写。</li><li>规则、断裂、PEC、曲边检测是同一条链，缺一则 ILT 停在后处理。</li><li>合理裁剪应只去掉通带外模态，否则曲线化没有光学理由。</li><li>出处：多束写入与曲线 ILT 的公开可制造性 / MRC 讨论。</li></ul>',7))])}const T=n(C,[["render",A]]);export{D as __pageData,T as default};
